import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  |> filter(fn: (r) => r.plant_id != "unknown")
  // Reject empty-scale reads. The station publishes whatever the load cell
  // settles on, and OLED_EMPTY_G (30 g, firmware) only blanks the DISPLAY —
  // it does not gate publishing, so a tag scanned with nothing on the scale
  // stores ~10-12 g against a real plant. The lightest pot here is ~120 g.
  |> filter(fn: (r) => r._value > 50.0)
  |> group(columns: ["plant_id"])
  // MIN, not median: on a watering day the station records twice, before and
  // after, and those are two different physical states — not one measurement
  // repeated. The minimum is the pre-water ("dry end") weight, the only series
  // whose day-over-day difference means one thing: water the plant actually
  // used. A median blends the two, so its difference mixes consumption with
  // the water just added.
  |> aggregateWindow(every: 1d, fn: min, createEmpty: false)
  |> keep(columns: ["_time", "_value", "plant_id"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  |> filter(fn: (r) => r.plant_id != "unknown")
  // Reject empty-scale reads. The station publishes whatever the load cell
  // settles on, and OLED_EMPTY_G (30 g, firmware) only blanks the DISPLAY —
  // it does not gate publishing, so a tag scanned with nothing on the scale
  // stores ~10-12 g against a real plant. The lightest pot here is ~120 g.
  |> filter(fn: (r) => r._value > 50.0)
  |> group(columns: ["plant_id"])
  // MIN, not median: on a watering day the station records twice, before and
  // after, and those are two different physical states — not one measurement
  // repeated. The minimum is the pre-water ("dry end") weight, the only series
  // whose day-over-day difference means one thing: water the plant actually
  // used. A median blends the two, so its difference mixes consumption with
  // the water just added.
  |> aggregateWindow(every: 1d, fn: min, createEmpty: false)
  // day-over-day change: the growth / water-loss signal. Needs at least TWO
  // days on which a plant was weighed, so it stays empty until the second session.
  |> difference(nonNegative: false)
  |> keep(columns: ["_time", "_value", "plant_id"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  |> filter(fn: (r) => r.plant_id != "unknown")
  |> filter(fn: (r) => r._value > 50.0)
  |> group(columns: ["plant_id"])
  // Water shows up as a jump between two CONSECUTIVE weighings of the same plant,
  // whenever they happened. That is "same-day if available, else the previous
  // weighing" without branching: weigh before and after and the pair is pre->post,
  // exact; weigh only after watering and the pair is yesterday->post, which is the
  // best estimate available. `difference` stamps the result at the later reading,
  // so it lands on the right day.
  |> difference(nonNegative: false)
  // A watering moves 20-160 g here; re-weighing an untouched pot differs by ~2-3 g.
  // The floor separates the two, and means a day with no watering yields NO point
  // rather than a row of zeros — this panel shows waterings, not days.
  |> filter(fn: (r) => r._value > 10.0)
  |> aggregateWindow(every: 1d, fn: max, createEmpty: false)
  |> keep(columns: ["_time", "_value", "plant_id"])

import "date"
import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "light" and r._field == "on" and r._value == 0.0)
  |> map(fn: (r) => ({ r with _value: float(v: date.hour(t: r._time)) + float(v: date.minute(t: r._time)) / 60.0 }))
  // Keep only plausible lamp-off times. `light/state` is RETAINED, so every
  // Telegraf reconnect replays it and lands a phantom OFF at the restart time —
  // one such artifact sits at 22:44 on 2026-07-30. The real switch-off is always
  // in the evening window, so anything outside it is not a lamp event.
  |> filter(fn: (r) => r._value >= 17.0 and r._value <= 21.5)
  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "lamp off (hour of day)")
